def drive(call, get, sleep):
    """Return the tools/call result, polling a task to completion if one comes back."""
    first = call()
    if first.get("resultType") != "task":
        return first
    task_id = first["taskId"]
    interval = first.get("pollIntervalMs", 1000)
    while True:
        sleep(interval / 1000)
        task = get(task_id)
        interval = task.get("pollIntervalMs", interval)
        if task["status"] == "completed":
            return task["result"]
        if task["status"] in ("failed", "cancelled"):
            raise RuntimeError(f"task {task_id} ended {task['status']}")

